import math
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Naive fused attention kernel (QK^T, masked fill, softmax, and att @ V).
# This is only for demonstration and is not highly optimized.
# It uses two kernel launches internally: one for QK^T and exponentiation,
# another for normalization and final matmul with V.

custom_attn_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>
#include <float.h>

// First kernel: compute att = exponentiated(QK^T * scale + mask_bias).
// Also save the row sum in sumexp (for normalizing).
// shape constraints (naive version):
//   q, k, v are float tensors with shape [B, nH, T, hS]
//   bias has shape [1, 1, maxSeq, maxSeq], but we'll only read up to T,T
// We do a 1D grid of dimension B*nH*T, with blockDim <= T (e.g. T=512).
// Each thread in x dimension processes a single t2 index (0 <= t2 < T).

__global__ void att_pass1_kernel(
    const float* __restrict__ q,
    const float* __restrict__ k,
    const float* __restrict__ bias,
    float* __restrict__ att,        // (B, nH, T, T)
    float* __restrict__ sumexp,     // (B, nH, T)
    int B, int nH, int T, int hS, int maxSeq
) {
    int global_idx = blockIdx.x; // each block corresponds to one (b, h, t)
    int t2 = threadIdx.x;        // each thread is a column in the T dimension

    if (global_idx >= (B * nH * T) || t2 >= T) return;

    int b  = global_idx / (nH * T);
    int tmp= global_idx % (nH * T);
    int h  = tmp / T;
    int t  = tmp % T;

    // q has shape (B, nH, T, hS), offset for this row
    const float* q_row = q + (((b * nH + h) * T) + t) * hS;
    // k has shape (B, nH, T, hS), offset for k's row
    const float* k_base = k + ((b * nH + h) * T) * hS;

    // compute dot product q_row dot k_row (where k_row is at index t2)
    float val = 0.0f;
    for(int i = 0; i < hS; i++){
        val += q_row[i] * k_base[t2 * hS + i];
    }

    // scale
    float scale = 1.0f / sqrtf((float)hS);
    val = val * scale;

    // apply causal mask via bias (if bias == 0 => masked)
    // bias shape is [1,1,maxSeq,maxSeq], we access bias[t, t2]
    // offset = t * maxSeq + t2 (in the last two dims)
    const float maskv = bias[(0 * 1 * maxSeq + 0 * maxSeq) + t * maxSeq + t2];
    // if maskv == 0 => we treat as -inf
    if(maskv == 0.0f){
        val = -INFINITY;
    }

    // exponentiate
    float m = __expf(val);

    // write to att
    int att_idx = (((b * nH + h) * T) + t) * T + t2;
    att[att_idx] = m;

    // use block-wide reduction in shared memory to accumulate sum of row
    // but we'll do a naive atomic approach on sumexp for brevity
    atomicAdd(&sumexp[(b * nH + h) * T + t], m);
}

// Second kernel: read from att, divide by sumexp, and multiply by V => output y
// att has shape [B, nH, T, T]
// v has shape   [B, nH, T, hS]
// y has shape   [B, T, nH, hS] (we'll reorder to [B, nH, T, hS] then reorder back in Python)
// for final: we want [B, T, nH*hS]. We'll reshape in Python.
__global__ void att_pass2_kernel(
    const float* __restrict__ att,
    const float* __restrict__ v,
    const float* __restrict__ sumexp,
    float* __restrict__ y,  // (B, nH, T, hS)
    int B, int nH, int T, int hS
) {
    int global_idx = blockIdx.x; // each block is (b, h, t)
    int tx = threadIdx.x;        // each thread processes some portion over T or hS
    if(global_idx >= (B * nH * T)) return;

    // We'll compute a single output row [b, h, t, hS]
    int b  = global_idx / (nH * T);
    int tmp= global_idx % (nH * T);
    int h  = tmp / T;
    int t  = tmp % T;

    extern __shared__ float smem[]; // could hold partial for hS if desired
    // We'll do a loop over hS in parallel, but let's do naive version:
    // one thread block has blockDim.x = hS or a portion. This is a simplistic approach.

    // sumexp for row
    float z = sumexp[(b * nH + h) * T + t];
    // if z == 0, avoid div by zero
    if(z == 0.f) z = 1e-9f;

    // We'll accumulate over the T dimension for each dimension in hS
    // We place partial sums in a local array, then write out.

    for(int i = tx; i < hS; i += blockDim.x){
        float out_val = 0.0f;
        // att row is [b, h, t, x], x from 0..T-1
        // v row is [b, h, x, i], x from 0..T-1
        for(int x = 0; x < T; x++){
            float att_val = att[(((b * nH + h) * T) + t) * T + x];
            float norm_att_val = att_val / z;
            out_val += norm_att_val * v[(((b * nH + h) * T) + x) * hS + i];
        }
        // store out_val to Y
        y[(((b * nH + h) * T) + t) * hS + i] = out_val;
    }
}

torch::Tensor custom_attn_cuda(
    torch::Tensor q, 
    torch::Tensor k, 
    torch::Tensor v, 
    torch::Tensor bias, 
    int B, int nH, int T, int hS, int maxSeq
) {
    // Create att and sumexp buffers
    auto att_options = torch::TensorOptions().dtype(q.dtype()).device(q.device());
    auto att = torch::zeros({B, nH, T, T}, att_options);
    auto sumexp = torch::zeros({B, nH, T}, att_options);

    // pass1: compute exponentiated (qk^T * scale + mask). store att, sumexp
    dim3 grid1(B * nH * T);
    dim3 block1(T); // T <= 1024 assumed
    att_pass1_kernel<<<grid1, block1>>>(
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        bias.data_ptr<float>(),
        att.data_ptr<float>(),
        sumexp.data_ptr<float>(),
        B, nH, T, hS, maxSeq
    );

    // pass2: normalize att, multiply by v => y
    auto y = torch::zeros({B, nH, T, hS}, att_options);
    dim3 grid2(B * nH * T);
    // we use min(hS, 1024) for threads
    dim3 block2(std::min(hS, 1024));
    size_t smem_size = 0; // naive, no shared mem usage beyond atomicAdd in pass1
    att_pass2_kernel<<<grid2, block2, smem_size>>>(
        att.data_ptr<float>(),
        v.data_ptr<float>(),
        sumexp.data_ptr<float>(),
        y.data_ptr<float>(),
        B, nH, T, hS
    );

    return y;
}

"""

custom_attn_cpp_source = r"""
torch::Tensor custom_attn_cuda(
    torch::Tensor q, 
    torch::Tensor k, 
    torch::Tensor v, 
    torch::Tensor bias, 
    int B, int nH, int T, int hS, int maxSeq
);
"""

# Build our fused attention op
custom_attn = load_inline(
    name="custom_attn",
    cpp_sources=custom_attn_cpp_source,
    cuda_sources=custom_attn_source,
    functions=["custom_attn_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Same architecture as Model, but uses a naive fused custom CUDA kernel
    to compute the attention part (QK^T -> masked fill -> softmax -> att@V).
    """
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        assert n_embd % n_head == 0
        # Q, K, V projection
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        # output projection
        self.c_proj = nn.Linear(n_embd, n_embd)
        # regularization
        self.attn_dropout = nn.Dropout(attn_pdrop)
        self.resid_dropout = nn.Dropout(resid_pdrop)
        # causal mask
        self.register_buffer(
            "bias", 
            torch.tril(torch.ones(max_seqlen, max_seqlen)).view(1, 1, max_seqlen, max_seqlen)
        )
        self.n_head = n_head
        self.n_embd = n_embd
        self.max_seqlen = max_seqlen

    def forward(self, x):
        B, T, C = x.size()
        # project to Q, K, V
        q, k, v = self.c_attn(x).split(self.n_embd, dim=2)
        # reshape to [B, nH, T, head_size]
        head_size = C // self.n_head
        q = q.view(B, T, self.n_head, head_size).transpose(1, 2).contiguous()
        k = k.view(B, T, self.n_head, head_size).transpose(1, 2).contiguous()
        v = v.view(B, T, self.n_head, head_size).transpose(1, 2).contiguous()

        # naive custom attention
        # expects q, k, v => [B, nH, T, head_size], plus the bias
        # returns y => [B, nH, T, head_size]
        # then we transpose back to [B, T, nH * head_size]
        y = custom_attn.custom_attn_cuda(
            q, k, v, self.bias, B, self.n_head, T, head_size, self.max_seqlen
        )

        y = y.transpose(1, 2).contiguous().view(B, T, C)
        y = self.attn_dropout(y)
        y = self.resid_dropout(self.c_proj(y))
        return y
